import{_ as e,o as i,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const l=JSON.parse('{"title":"Định nghĩa file spec.md","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/definition/spec.md","filePath":"feature/system-maintenance/definition/spec.md"}'),c={name:"feature/system-maintenance/definition/spec.md"};function o(h,t,r,d,u,s){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="đinh-nghia-file-spec-md" tabindex="-1">Định nghĩa file <code>spec.md</code> <a class="header-anchor" href="#đinh-nghia-file-spec-md" aria-label="Permalink to &quot;Định nghĩa file `spec.md`&quot;">​</a></h1><h2 id="muc-đich" tabindex="-1">Mục đích <a class="header-anchor" href="#muc-đich" aria-label="Permalink to &quot;Mục đích&quot;">​</a></h2><p><code>spec.md</code> trả lời câu hỏi <strong>&quot;Feature này làm gì, cho ai, đúng ra sao&quot;</strong> — chốt nghiệp vụ trước khi bất kỳ ai viết code. Đây là hợp đồng giữa BA và Dev: dev không tự suy diễn nghiệp vụ, mọi câu hỏi &quot;case này xử lý sao&quot; phải có câu trả lời trong file này (hoặc phải bổ sung vào file này trước khi code).</p><h2 id="ai-viet-khi-nao-viet" tabindex="-1">Ai viết, khi nào viết <a class="header-anchor" href="#ai-viet-khi-nao-viet" aria-label="Permalink to &quot;Ai viết, khi nào viết&quot;">​</a></h2><p>BA/Trung viết trước khi giao task cho dev. Trạng thái <code>Draft</code> cho tới khi BA confirm xong nghiệp vụ, dev <strong>không code khi spec còn Draft có phần chưa rõ</strong>.</p><h2 id="cau-truc-bat-buoc-theo-mau-đang-dung-trong-repo" tabindex="-1">Cấu trúc bắt buộc (theo mẫu đang dùng trong repo) <a class="header-anchor" href="#cau-truc-bat-buoc-theo-mau-đang-dung-trong-repo" aria-label="Permalink to &quot;Cấu trúc bắt buộc (theo mẫu đang dùng trong repo)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Header table</td><td>FR Code, Feature name, Domain, Role được phép dùng, Version, Trạng thái tài liệu</td></tr><tr><td>1. Objective</td><td>Một câu mô tả feature giải quyết vấn đề gì</td></tr><tr><td>2. User Story</td><td>Format &quot;Là một [role], tôi muốn..., để...&quot;</td></tr><tr><td>3. Acceptance Criteria</td><td>Danh sách điều kiện nghiệp vụ phải đúng — đây là nguồn cho <code>test.md</code> sau này, viết đủ chi tiết để tự sinh test case được</td></tr><tr><td>4. UI/UX</td><td>Route/trang liên quan, hành vi hiển thị chính (không phải wireframe chi tiết, chỉ đủ để dev hiểu luồng)</td></tr><tr><td>5. API Contract (đề xuất)</td><td>Method + path + response shape đề xuất — <strong>chưa final</strong>, <code>plan.md</code> sẽ chốt lại khi thiết kế kỹ thuật</td></tr><tr><td>6. Error Handling</td><td>Các lỗi nghiệp vụ cần xử lý và cách xử lý</td></tr><tr><td>7. Edge Cases</td><td>Case biên (user mới, dữ liệu rỗng, quyền hạn chế...)</td></tr><tr><td>8. Definition of Done</td><td>Điều kiện để coi feature &quot;xong&quot; ở mức nghiệp vụ</td></tr><tr><td>Out of Scope</td><td>Ghi rõ cái gì KHÔNG thuộc FR này — tránh dev tự mở rộng phạm vi</td></tr><tr><td>Tham chiếu BA</td><td>Link tới tài liệu BA gốc (<code>docs/BA/*.md</code>) làm nguồn nghiệp vụ</td></tr></tbody></table><h2 id="ranh-gioi-voi-cac-file-khac" tabindex="-1">Ranh giới với các file khác <a class="header-anchor" href="#ranh-gioi-voi-cac-file-khac" aria-label="Permalink to &quot;Ranh giới với các file khác&quot;">​</a></h2><ul><li><code>spec.md</code> nói <strong>CÁI GÌ</strong> (what) — không nói <strong>LÀM SAO</strong> (how) ở mức code/database/thư viện. Chi tiết kỹ thuật thuộc về <code>plan.md</code>.</li><li>Nếu trong lúc code phát sinh câu hỏi nghiệp vụ mới → sửa <code>spec.md</code> trước (và note lại), không tự quyết trong code hoặc chỉ ghi trong <code>plan.md</code>/comment.</li></ul>',9)])])}const m=e(c,[["render",o]]);export{l as __pageData,m as default};
